#include "RealNeuralChipProtocol.h"
#include "RealNeuralChipPacket.h"
#include "../utils/TimeSync.h"
namespace dnxr { RealNeuralChipPacket RealNeuralChipProtocol::buildPacket(const SafeNeuralStimulusCommand& c,const std::string& sid,const std::string& prev) const { RealNeuralChipPacket p; p.protocolVersion=1; p.packetId=c.sequenceId; p.sequenceId=c.sequenceId; p.sessionId=sid; p.monotonicTimestamp=c.monotonicTimestampMs>0?c.monotonicTimestampMs:TimeSync::nowMs(); p.patientCalibrationHash=c.calibrationProfileId; p.commandType="safe_full_dive_stimulus"; p.payload=c.boundedChannels; p.channelCount=static_cast<std::uint32_t>(p.payload.size()); p.payloadLength=static_cast<std::uint32_t>(p.payload.size()*sizeof(float)); p.previousCommandHash=prev; p.previousPacketHash=prev; p.safetyMode=c.safetyMode; p.emergencyCutoff=!c.allowStimulusDispatch; p.commandHash=computePacketHash(p); p.payloadHash=p.commandHash; p.signature="simulation_signature_required_for_real_transport"; return p; } bool RealNeuralChipProtocol::validateLockedClinicalPrerequisites(bool gate,bool att,bool evidence,bool stop) const { return gate&&att&&evidence&&stop; } }
